// ScratchPad/Session13/Session13CollectionContractDemo.cs
public sealed class Session13CollectionContractDemo
{
    public void Run()
    {
        var session13Repository = new ClockEntryRepository();

        var completedEntry = new ClockEntry(
            13,
            new DateTime(2026, 1, 15, 9, 0, 0));
        completedEntry.ClockOutEntry(
            new DateTime(2026, 1, 15, 17, 0, 0));

        var openEntry = new ClockEntry(
            13,
            new DateTime(2026, 1, 16, 9, 0, 0));

        session13Repository.SaveClockEntry(completedEntry);
        session13Repository.SaveClockEntry(openEntry);

        IEnumerable<ClockEntry> entries =
            session13Repository.GetEmployeeClockEntries(
                13,
                new DateTime(2026, 1, 1),
                new DateTime(2026, 1, 31));

        // These do not compile through the IEnumerable<ClockEntry> contract.
        // entries.Add(openEntry);
        // ClockEntry firstEntry = entries[0];
        // int countProperty = entries.Count;

        Console.WriteLine($"Completed entries: {entries.Count()}");
        Display(entries);
    }

    public void Display(IEnumerable<ClockEntry> entries)
    {
        foreach (ClockEntry entry in entries)
        {
            Console.WriteLine(
                $"Employee {entry.EmployeeId}: {entry.ClockIn} to {entry.Clockout}");
        }
    }
}

